text:
Explore how university performance develops over time, who is more often found in each trajectory, and how adjusted trajectory probabilities differ across fields of study.
#| '!! shinylive warning !!': |
#|   shinylive does not work in self-contained HTML documents.
#|   Please set `embed-resources: false` in your metadata.
#| standalone: true
#| viewerHeight: 900

library(shiny)

# ============================================================
# DATA
# ============================================================

# ------------------------------------------------------------
# 1. Six empirical GBTM trajectories
# ------------------------------------------------------------
# Shapes are visually reconstructed from Figure 1 of the paper
# (the original model-predicted coordinates were not available).
# Published group prevalence is taken from the final article.

traj &lt;- data.frame(
  year = rep(1:7, 6),
  group = rep(paste0("G", 1:6), each = 7),
  performance = c(
    # G1 Early descending
    32, 4, 0.5, 0, 0, 0, 0,
    # G2 Stable descending
    67, 52, 30, 10, 2, 0, 0,
    # G3 Mid-stable performance
    55, 51, 49, 49, 52, 56, 60,
    # G4 Upward performance
    73, 77, 81, 85, 90, 94, 97,
    # G5 High performance & decline
    86, 87, 88, 83, 50, 4, 0,
    # G6 High-stable performance
    97, 98, 99, 99, 99, 97, 89
  )
)

meta &lt;- data.frame(
  group = paste0("G", 1:6),
  trajectory = c(
    "Early descending",
    "Stable descending",
    "Mid-stable performance",
    "Upward performance",
    "High performance & decline",
    "High-stable performance"
  ),
  share = c(9.7, 5.5, 8.0, 27.0, 6.1, 43.7),
  colour = c(
    "#1A476F",
    "#90353B",
    "#55752F",
    "#E37E00",
    "#6E8E84",
    "#C10534"
  ),
  description = c(
    "Low performance in the first year, followed by a rapid fall to almost no academic progress.",
    "Relatively high initial performance followed by a progressive decline towards no academic progress.",
    "Performance remains around the middle of the scale, with a modest increase in later years.",
    "High initial performance followed by progressive improvement towards very high performance.",
    "Very high performance during the first years, followed by a sharp late decline.",
    "Consistently very high performance across the observation period."
  ),
  stringsAsFactors = FALSE
)

# Final status after seven years (Table 4, final article)
outcomes &lt;- data.frame(
  group = paste0("G", 1:6),
  dropout = c(97.3, 96.5, 8.3, 0.3, 67.1, 0.2),
  on_time = c(0.0, 0.1, 0.3, 56.6, 4.8, 92.9),
  delayed = c(0.0, 0.0, 17.2, 38.3, 9.8, 6.2),
  persistence = c(2.7, 3.4, 74.2, 4.8, 18.2, 0.6)
)

# ------------------------------------------------------------
# 2. Descriptive composition of the six trajectories
#    (Table A1, percentages within each category)
# ------------------------------------------------------------

comp &lt;- data.frame(
  variable = character(),
  category = character(),
  n = integer(),
  G1 = numeric(), G2 = numeric(), G3 = numeric(),
  G4 = numeric(), G5 = numeric(), G6 = numeric(),
  stringsAsFactors = FALSE
)

add_comp &lt;- function(variable, category, n, values) {
  data.frame(
    variable = variable,
    category = category,
    n = n,
    G1 = values[1], G2 = values[2], G3 = values[3],
    G4 = values[4], G5 = values[5], G6 = values[6],
    stringsAsFactors = FALSE
  )
}

comp &lt;- rbind(
  comp,

  add_comp("Field of study", "Arts & Humanities", 3693,
           c(15.00, 7.74, 6.99, 23.23, 5.47, 41.57)),
  add_comp("Field of study", "Social & Law", 12188,
           c(7.88, 5.46, 6.21, 25.78, 4.86, 49.81)),
