  add_comp("Gender", "Women", 16643,
           c(7.50, 4.27, 5.23, 24.66, 3.60, 54.74)),
  add_comp("Gender", "Men", 13749,
           c(12.65, 6.75, 10.21, 32.33, 4.83, 33.23)),

