# ------------------------------------------------------------
# 3. Adjusted predicted probabilities across fields
#    Tables 5–7 in the final article.
#    Four analytical routes:
#      G1 + G2 = Dropout trajectory
#      G3      = Slow progression
#      G4      = Successful recovery
#      G6      = Optimal route
# G5 is retained in model estimation but not displayed in this
# second analytical stage, following the published article.
# ------------------------------------------------------------

pred &lt;- data.frame(
  variable = character(),
  field = character(),
  category = character(),
  dropout = numeric(),
  slow = numeric(),
  recovery = numeric(),
  optimal = numeric(),
  stringsAsFactors = FALSE
)

add_pred &lt;- function(variable, field, category, vals) {
  data.frame(
    variable = variable,
    field = field,
    category = category,
    dropout = vals[1],
    slow = vals[2],
    recovery = vals[3],
    optimal = vals[4],
    stringsAsFactors = FALSE
  )
}

# Parental education
pred &lt;- rbind(
  pred,
  add_pred("Parental education", "Arts & Humanities", "Non-university", c(.208,.068,.242,.428)),
