# ============================================================
# HELPERS
# ============================================================

trajectory_svg &lt;- function(weights = NULL, selected = "All") {

  W &lt;- 760
  H &lt;- 390
  left &lt;- 58
  right &lt;- 18
  top &lt;- 24
  bottom &lt;- 47

  pw &lt;- W - left - right
  ph &lt;- H - top - bottom

  xmap &lt;- function(y) left + (y - 1) / 6 * pw
  ymap &lt;- function(p) top + (100 - p) / 100 * ph

  # grid
  grid &lt;- paste0(
    sapply(
      seq(0, 100, 20),
      function(v) {
        paste0(
          '&lt;line x1="', left, '" y1="', ymap(v),
          '" x2="', W-right, '" y2="', ymap(v),
          '" stroke="#eeeeee" stroke-width="1"/&gt;',
          '&lt;text x="', left-10, '" y="', ymap(v)+4,
          '" text-anchor="end" font-size="10" fill="#888"&gt;',
          v, '%&lt;/text&gt;'
        )
      }
    ),
    collapse = ""
  )

  xlabels &lt;- paste0(
    sapply(
      1:7,
      function(y) {
        paste0(
          '&lt;text x="', xmap(y), '" y="', H-18,
          '" text-anchor="middle" font-size="10" fill="#777"&gt;',
          'Y', y, '&lt;/text&gt;'
        )
      }
    ),
    collapse = ""
  )

  paths &lt;- ""

  if (!is.null(weights)) {
    mx &lt;- max(weights)
  }

  for (i in seq_len(nrow(meta))) {

    g &lt;- meta$group[i]
    col &lt;- meta$colour[i]
    d &lt;- traj[traj$group == g, ]

    pts &lt;- paste0(
      xmap(d$year), ",", ymap(d$performance),
      collapse = " "
    )

    if (!is.null(weights)) {
      rel &lt;- sqrt(weights[g] / mx)
      sw &lt;- 2.4 + 5.2 * rel
      op &lt;- 0.24 + 0.76 * rel
    } else if (!is.null(selected) && selected != "All") {
      if (g == selected) {
        sw &lt;- 6
        op &lt;- 1
      } else {
        sw &lt;- 2.4
        op &lt;- 0.16
      }
    } else {
      sw &lt;- 4
      op &lt;- 0.92
    }

    paths &lt;- paste0(
      paths,
      '&lt;polyline points="', pts,
      '" fill="none" stroke="', col,
      '" stroke-width="', sw,
      '" stroke-linecap="round" stroke-linejoin="round"',
      ' opacity="', op, '"/&gt;'
    )
  }

  axis_label &lt;- paste0(
    '&lt;text x="15" y="', top + ph/2,
    '" transform="rotate(-90 15 ', top + ph/2, ')"',
    ' text-anchor="middle" font-size="11" fill="#666"&gt;',
    'Performance rate&lt;/text&gt;'
  )

  HTML(
    paste0(
      '&lt;svg viewBox="0 0 ', W, ' ', H, '"',
      ' style="width:100%;height:auto;display:block;"&gt;',
      grid,
      '&lt;line x1="', left, '" y1="', top+ph,
      '" x2="', W-right, '" y2="', top+ph,
      '" stroke="#bdbdbd" stroke-width="1"/&gt;',
      xlabels,
      axis_label,
      paths,
      '&lt;/svg&gt;'
    )
  )
}


trajectory_legend &lt;- function() {
  div(
    class = "legend",
    lapply(
      seq_len(nrow(meta)),
      function(i) {
        div(
          class = "legend-item",
          div(
            class = "legend-line",
            style = paste0("background:", meta$colour[i], ";")
          ),
          span(
            paste0(
              meta$group[i], " · ",
              meta$trajectory[i], " (",
              sprintf("%.1f", meta$share[i]), "%)"
            )
          )
        )
      }
    )
  )
}


dumbbell_svg &lt;- function(d, stars, group1, group2) {

  routes &lt;- c("dropout", "slow", "recovery", "optimal")
  labels &lt;- unname(route_labels[routes])

  W &lt;- 760
  H &lt;- 330
  left &lt;- 185
  right &lt;- 75
  top &lt;- 45
  bottom &lt;- 38

  maxp &lt;- 0.70
  pw &lt;- W - left - right

  xmap &lt;- function(p) left + p / maxp * pw

  # four row positions
  ys &lt;- c(75, 135, 195, 255)

  # axis / grid
  ticks &lt;- seq(0, .7, by = .1)

  grid &lt;- paste0(
    sapply(
      ticks,
      function(v) {
        paste0(
          '&lt;line x1="', xmap(v), '" y1="', top,
          '" x2="', xmap(v), '" y2="', H-bottom,
          '" stroke="#eeeeee" stroke-width="1"/&gt;',
          '&lt;text x="', xmap(v), '" y="', H-14,
          '" text-anchor="middle" font-size="10" fill="#888"&gt;',
          round(v*100), '%&lt;/text&gt;'
        )
      }
    ),
    collapse = ""
  )

  rows &lt;- ""

  for (i in seq_along(routes)) {

    r &lt;- routes[i]
    y &lt;- ys[i]

    a &lt;- d[d$category == group1, r]
    b &lt;- d[d$category == group2, r]

    sig_i &lt;- stars$stars[stars$route == labels[i]]
    if (length(sig_i) == 0) sig_i &lt;- ""

    rows &lt;- paste0(
      rows,

      '&lt;text x="', left-12, '" y="', y+4,
      '" text-anchor="end" font-size="11" fill="#444"&gt;',
      labels[i], '&lt;/text&gt;',

      '&lt;line x1="', xmap(a), '" y1="', y,
      '" x2="', xmap(b), '" y2="', y,
      '" stroke="#c9c9c9" stroke-width="3" stroke-linecap="round"/&gt;',

      '&lt;circle cx="', xmap(a), '" cy="', y,
      '" r="6" fill="#4E79A7"/&gt;',

      '&lt;circle cx="', xmap(b), '" cy="', y,
      '" r="6" fill="#C95D5D"/&gt;',

      '&lt;text x="', xmap(a), '" y="', y-11,
      '" text-anchor="middle" font-size="10" fill="#4E79A7" font-weight="600"&gt;',
      sprintf("%.1f%%", 100*a), '&lt;/text&gt;',

      '&lt;text x="', xmap(b), '" y="', y+22,
      '" text-anchor="middle" font-size="10" fill="#C95D5D" font-weight="600"&gt;',
      sprintf("%.1f%%", 100*b), '&lt;/text&gt;',

      '&lt;text x="', W-right+14, '" y="', y+4,
      '" text-anchor="start" font-size="10" fill="#777"&gt;',
      sig_i, '&lt;/text&gt;'
    )
  }

  # group legend
  legend &lt;- paste0(
    '&lt;circle cx="', left, '" cy="20" r="5" fill="#4E79A7"/&gt;',
    '&lt;text x="', left+10, '" y="24" font-size="10.5" fill="#555"&gt;',
    group1, '&lt;/text&gt;',
    '&lt;circle cx="', left+210, '" cy="20" r="5" fill="#C95D5D"/&gt;',
    '&lt;text x="', left+220, '" y="24" font-size="10.5" fill="#555"&gt;',
    group2, '&lt;/text&gt;'
  )

  HTML(
    paste0(
      '&lt;svg viewBox="0 0 ', W, ' ', H, '"',
      ' style="width:100%;height:auto;display:block;"&gt;',
      grid,
      legend,
      rows,
      '&lt;/svg&gt;'
    )
  )
}

# ============================================================
# SERVER
# ============================================================

server &lt;- function(input, output, session) {

  # ----------------------------------------------------------
  # Dynamic controls
  # ----------------------------------------------------------

  output$controls &lt;- renderUI({

    if (input$view == "trajectories") {

      tagList(
        div(class = "control-title", "Six empirical trajectories"),

        selectInput(
          "traj_select",
          "Highlight trajectory",
          choices = c(
            "All trajectories" = "All",
            setNames(meta$group, paste0(meta$group, " · ", meta$trajectory))
          ),
          selected = "All"
        ),

        p(
          class = "control-note",
          "The six GBTM groups describe ideal-typical patterns of annual academic performance over seven years. Select one trajectory to connect its shape with students' final academic status."
        )
      )

    } else if (input$view == "composition") {

      v &lt;- if (is.null(input$comp_var)) "Age" else input$comp_var
      cats &lt;- comp$category[comp$variable == v]
      default_cat &lt;- if (v == "Age") "26 or more" else cats[1]

      tagList(
        div(class = "control-title", "Who follows each trajectory?"),

        selectInput(
          "comp_var",
          "Variable",
          choices = unique(comp$variable),
          selected = v
        ),

        selectInput(
          "comp_category",
          "Category",
          choices = cats,
          selected = default_cat
        ),

        p(
          class = "control-note",
          "The line shapes remain fixed. Their visual prominence reflects the descriptive distribution of the selected group across the six trajectories."
        ),

        p(
          class = "control-note",
          strong("Important: "),
          "these are unadjusted descriptive percentages, not causal effects."
        )
      )

    } else {

      v &lt;- if (is.null(input$field_var)) "Age" else input$field_var

      tagList(
        div(class = "control-title", "Inequalities across fields"),

        selectInput(
          "field_var",
          "Compare by",
          choices = c("Age", "Gender", "Parental education"),
          selected = v
        ),

        selectInput(
          "field_select",
          "Field of study",
          choices = c(
            "Arts & Humanities",
            "Social & Law",
            "Health",
            "Sciences",
            "Engineering & Architecture"
          ),
          selected = "Engineering & Architecture"
        ),

        p(
          class = "control-note",
          "This view uses adjusted predicted probabilities from the published multinomial models."
        ),

        p(
          class = "control-note",
          strong("Four analytical routes: "),
          "G1+G2 = Dropout; G3 = Slow progression; G4 = Successful recovery; G6 = Optimal route. G5 was retained in estimation but omitted from this display, following the article."
        )
      )
    }
  })


  # ----------------------------------------------------------
  # Plot headings
  # ----------------------------------------------------------

  output$plot_title &lt;- renderUI({

    if (input$view == "trajectories") {
      HTML("Academic performance across seven years")
    } else if (input$view == "composition") {
      HTML("The same trajectories, viewed through a social profile")
    } else {
      HTML("Adjusted probability of following each analytical route")
    }
  })


  output$plot_subtitle &lt;- renderUI({

    if (input$view == "trajectories") {
      HTML("Six-group GBTM")
    } else if (input$view == "composition") {
      HTML("Descriptive distribution · Table A1")
    } else {
      req(input$field_var, input$field_select)
      HTML(paste(input$field_select, "·", input$field_var))
    }
  })


  # ----------------------------------------------------------
  # Main plot
  # ----------------------------------------------------------

  output$main_plot &lt;- renderUI({

    if (input$view == "trajectories") {

      selected &lt;- if (is.null(input$traj_select)) "All" else input$traj_select
      trajectory_svg(selected = selected)

    } else if (input$view == "composition") {

      req(input$comp_var, input$comp_category)

      row &lt;- comp[
        comp$variable == input$comp_var &
        comp$category == input$comp_category,
      ]

      weights &lt;- as.numeric(row[paste0("G", 1:6)])
      names(weights) &lt;- paste0("G", 1:6)

      trajectory_svg(weights = weights)

    } else {

      req(input$field_var, input$field_select)

      d &lt;- pred[
        pred$variable == input$field_var &
        pred$field == input$field_select,
      ]

      cats &lt;- unique(d$category)
      req(length(cats) == 2)

      s &lt;- sig[
        sig$variable == input$field_var &
        sig$field == input$field_select,
      ]

      dumbbell_svg(
        d = d,
        stars = s,
        group1 = cats[1],
        group2 = cats[2]
      )
    }
  })


  # ----------------------------------------------------------
  # Legend
  # ----------------------------------------------------------

  output$legend_ui &lt;- renderUI({

    if (input$view %in% c("trajectories", "composition")) {
      trajectory_legend()
    } else {
      div(
        class = "mini-key",
        HTML("Stars indicate the published Wald test for the difference between the two categories: *** p ≤ .001 · ** p ≤ .01 · * p ≤ .05 · n.s. = not significant.")
      )
    }
  })


  # ----------------------------------------------------------
  # Detail area
  # ----------------------------------------------------------

  output$detail &lt;- renderUI({

    # ---- Trajectory detail ----------------------------------
    if (input$view == "trajectories") {

      selected &lt;- if (is.null(input$traj_select)) "All" else input$traj_select

      if (selected == "All") {

        return(
          div(
            class = "detail-card",
            div(class = "detail-kicker", "Cohort overview"),
            div(class = "detail-title", "Most students follow high-performance trajectories"),
            div(
              class = "detail-text",
              "The largest group is G6, high-stable performance (43.7%), followed by G4, upward performance (27.0%). Select a trajectory to see how its performance pattern relates to final academic status."
            )
          )
        )
      }

      m &lt;- meta[meta$group == selected, ]
      o &lt;- outcomes[outcomes$group == selected, ]

      div(
        class = "detail-card",
        div(
          class = "detail-kicker",
          paste0(m$group, " · ", sprintf("%.1f", m$share), "% of students")
        ),
        div(class = "detail-title", m$trajectory),
        div(class = "detail-text", m$description),

        div(
          class = "metric-row",

          div(
            class = "metric",
            div(class = "metric-value", sprintf("%.1f%%", o$dropout)),
            div(class = "metric-label", "Dropout")
          ),

          div(
            class = "metric",
            div(class = "metric-value", sprintf("%.1f%%", o$on_time)),
            div(class = "metric-label", "Graduated on time")
          ),

          div(
            class = "metric",
            div(class = "metric-value", sprintf("%.1f%%", o$delayed)),
            div(class = "metric-label", "Graduated with delay")
          ),

          div(
            class = "metric",
            div(class = "metric-value", sprintf("%.1f%%", o$persistence)),
            div(class = "metric-label", "Still enrolled after 7 years")
          )
        )
      )

    # ---- Composition detail ---------------------------------
    } else if (input$view == "composition") {

      req(input$comp_var, input$comp_category)

      row &lt;- comp[
        comp$variable == input$comp_var &
        comp$category == input$comp_category,
      ]

      vals &lt;- as.numeric(row[paste0("G", 1:6)])
      overall &lt;- meta$share
      deltas &lt;- vals - overall

      bar_rows &lt;- lapply(
        seq_len(6),
        function(i) {

          div(
            class = "dist-grid",

            div(
              class = "dist-label",
              paste0(meta$group[i], " · ", meta$trajectory[i])
            ),

            div(
              class = "dist-track",

              div(
                class = "dist-fill",
                style = paste0(
                  "width:", vals[i], "%;",
                  "background:", meta$colour[i], ";"
                )
              ),

              div(
                class = "overall-marker",
                style = paste0("left:", overall[i], "%;")
              )
            ),

            div(
              class = "dist-value",
              sprintf("%.1f%%", vals[i])
            ),

            div(
              class = "dist-delta",
              paste0(
                ifelse(deltas[i] &gt;= 0, "+", ""),
                sprintf("%.1f", deltas[i]),
                " pp"
              )
            )
          )
        }
      )

      div(
        class = "detail-card",

        div(
          class = "detail-kicker",
          paste0(input$comp_var, " · N = ", format(row$n, big.mark = ","))
        ),

        div(class = "detail-title", input$comp_category),

        div(
          class = "detail-text",
          "Distribution of this group across the six empirical trajectories. The black marker shows the overall cohort share for each trajectory."
        ),

        do.call(tagList, bar_rows),

        div(
          class = "mini-key",
          "pp = percentage-point difference from the overall cohort."
        )
      )

    # ---- Field comparison detail ----------------------------
    } else {

      req(input$field_var, input$field_select)

      d &lt;- pred[
        pred$variable == input$field_var &
        pred$field == input$field_select,
      ]

      cats &lt;- unique(d$category)

      # calculate largest absolute gap across the four routes
      diffs &lt;- c(
        dropout = d$dropout[d$category == cats[2]] - d$dropout[d$category == cats[1]],
        slow = d$slow[d$category == cats[2]] - d$slow[d$category == cats[1]],
        recovery = d$recovery[d$category == cats[2]] - d$recovery[d$category == cats[1]],
        optimal = d$optimal[d$category == cats[2]] - d$optimal[d$category == cats[1]]
      )

      biggest &lt;- names(which.max(abs(diffs)))
      diff_val &lt;- diffs[biggest]

      a &lt;- d[d$category == cats[1], biggest]
      b &lt;- d[d$category == cats[2], biggest]

      div(
        class = "detail-card",

        div(
          class = "detail-kicker",
          paste0(input$field_select, " · adjusted model")
        ),

        div(
          class = "detail-title",
          paste0("Largest contrast: ", route_labels[biggest])
        ),

        div(
          class = "detail-text",
          paste0(
            cats[1], ": ", sprintf("%.1f%%", 100*a),
            " · ",
            cats[2], ": ", sprintf("%.1f%%", 100*b),
            " · difference: ",
            ifelse(diff_val &gt;= 0, "+", ""),
            sprintf("%.1f", 100*diff_val),
            " percentage points."
          )
        ),

        div(
          class = "mini-key",
          "Each comparison comes from a separate multinomial model including the selected characteristic, field of study, their interaction, and the control variables reported in the article."
        )
      )
    }
  })
}

