# ============================================================
# SERVER
# ============================================================

server &lt;- function(input, output, session) {

  observeEvent(input$clear_subfields, {
    updateSelectizeInput(
      session,
      "subfields",
      selected = character(0)
    )
  })

  output$space &lt;- renderUI({

    layers &lt;- input$layers
    if (is.null(layers)) {
      layers &lt;- character(0)
    }

    # --------------------------------------------------------
    # Visible data
    # --------------------------------------------------------

    active_d &lt;- coords[
      coords$type == "active" &
        coords$variable == input$variable,
      ,
      drop = FALSE
    ]

    sub_d &lt;- coords[
      coords$type == "subfield",
      ,
      drop = FALSE
    ]

    if (!is.null(input$field_filter) && input$field_filter != "All") {
      sub_d &lt;- sub_d[
        sub_d$stem == input$field_filter,
        ,
        drop = FALSE
      ]
    }

    selected &lt;- input$subfields
    if (is.null(selected)) {
      selected &lt;- character(0)
    }

    # --------------------------------------------------------
    # Fixed plotting range
    #
    # Keep the same factorial-space reference frame for every
    # variable, layer combination and subdiscipline filter.
    # This prevents the plot from rescaling during exploration
    # and makes positions directly comparable across views.
    # --------------------------------------------------------

    xr &lt;- c(-0.80, 2.25)
    yr &lt;- c(-2.20, 0.80)

    # --------------------------------------------------------
    # SVG geometry
    # --------------------------------------------------------

    W &lt;- 1000
    H &lt;- 570
    left &lt;- 90
    right &lt;- 970
    top &lt;- 35
    bottom &lt;- 495

    sx &lt;- function(x) {
      left + (x - xr[1]) / (xr[2] - xr[1]) * (right - left)
    }

    sy &lt;- function(y) {
      bottom - (y - yr[1]) / (yr[2] - yr[1]) * (bottom - top)
    }

    # --------------------------------------------------------
    # Axes
    # --------------------------------------------------------

    axis_html &lt;- ""

    if (xr[1] &lt;= 0 && xr[2] &gt;= 0) {
      axis_html &lt;- paste0(
        axis_html,
        '&lt;line x1="', sx(0), '" y1="', top,
        '" x2="', sx(0), '" y2="', bottom,
        '" stroke="#cccccc" stroke-width="1"/&gt;'
      )
    }

    if (yr[1] &lt;= 0 && yr[2] &gt;= 0) {
      axis_html &lt;- paste0(
        axis_html,
        '&lt;line x1="', left, '" y1="', sy(0),
        '" x2="', right, '" y2="', sy(0),
        '" stroke="#cccccc" stroke-width="1"/&gt;'
      )
    }

    # --------------------------------------------------------
    # Clusters
    # --------------------------------------------------------

    cluster_html &lt;- ""

    if ("clusters" %in% layers) {

      cluster_html &lt;- paste(
        vapply(
          seq_len(nrow(clusters)),
          function(i) {

            px &lt;- sx(clusters$dim1[i])
            py &lt;- sy(clusters$dim2[i])

            radius &lt;- 8 + clusters$share[i] * 0.45
            colour &lt;- unname(cluster_colours[clusters$gender[i]])

            dx &lt;- if (clusters$dim1[i] &lt; 0) -12 else 12
            anchor &lt;- if (clusters$dim1[i] &lt; 0) "end" else "start"

            # Extra vertical separation for the very close C2/C3 pair
            dy &lt;- if (clusters$cluster[i] == "C2") -13 else if (clusters$cluster[i] == "C3") 18 else -11

            title_txt &lt;- paste0(
              clusters$cluster[i],
              " · ", sprintf("%.1f%%", clusters$share[i]),
              " · ", clusters$gender[i],
              " · ", clusters$orientation[i],
              " | ", clusters$profile[i],
              " | Dim 1: ", sprintf("%.3f", clusters$dim1[i]),
              " | Dim 2: ", sprintf("%.3f", clusters$dim2[i])
            )

            hover_txt &lt;- paste0(
              clusters$cluster[i],
              " · ", sprintf("%.1f%%", clusters$share[i]),
              " · ", clusters$gender[i],
              " · ", clusters$orientation[i]
            )

            paste0(
              '&lt;g class="cluster-point"&gt;',
              '&lt;circle class="cluster-symbol"',
              ' cx="', px, '" cy="', py, '" r="', radius, '"',
              ' fill="', colour, '" fill-opacity="0.16"',
              ' stroke="', colour, '" stroke-width="2.3"&gt;',
              '&lt;title&gt;', esc(title_txt), '&lt;/title&gt;',
              '&lt;/circle&gt;',
              svg_text(
                px + dx,
                py + dy,
                clusters$cluster[i],
                size = 12,
                colour = colour,
                anchor = anchor,
                weight = 700
              ),
              svg_text(
                px + dx,
                py + dy + 14,
                hover_txt,
                size = 10,
                colour = colour,
                anchor = anchor,
                weight = 500,
                class = "hover-label"
              ),
              '&lt;/g&gt;'
            )
          },
          character(1)
        ),
        collapse = ""
      )
    }

    # --------------------------------------------------------
    # Subdisciplines
    # --------------------------------------------------------

    subfield_html &lt;- ""

    if ("subfields" %in% layers && nrow(sub_d) &gt; 0) {

      subfield_html &lt;- paste(
        vapply(
          seq_len(nrow(sub_d)),
          function(i) {

            px &lt;- sx(sub_d$dim1[i])
            py &lt;- sy(sub_d$dim2[i])

            is_selected &lt;- sub_d$label[i] %in% selected
            fill &lt;- if (is_selected) "#C95D5D" else "#bdbdbd"
            size &lt;- if (is_selected) 8 else 5.5

            if (sub_d$stem[i] == "STEM") {
              symbol &lt;- paste0(
                '&lt;circle class="subfield-symbol"',
                ' cx="', px, '" cy="', py, '" r="', size, '"',
                ' fill="', fill, '" stroke="white" stroke-width="1.3"/&gt;'
              )
            } else {
              symbol &lt;- paste0(
                '&lt;rect class="subfield-symbol"',
                ' x="', px - size, '" y="', py - size, '"',
                ' width="', 2 * size, '" height="', 2 * size, '"',
                ' rx="1.2" fill="', fill, '"',
                ' stroke="white" stroke-width="1.3"/&gt;'
              )
            }

            dx &lt;- if (sub_d$dim1[i] &gt; 0.6) -10 else 10
            anchor &lt;- if (sub_d$dim1[i] &gt; 0.6) "end" else "start"

            title_txt &lt;- paste0(
              sub_d$label[i],
              " · ", sub_d$stem[i],
              " | Dim 1: ", sprintf("%.3f", sub_d$dim1[i]),
              " | Dim 2: ", sprintf("%.3f", sub_d$dim2[i])
            )

            persistent &lt;- ""
            if (is_selected && isTRUE(input$labels)) {
              persistent &lt;- svg_text(
                px + dx,
                py - 9,
                sub_d$label[i],
                size = 11,
                colour = "#333333",
                anchor = anchor,
                weight = 600
              )
            }

            paste0(
              '&lt;g class="subfield-point"&gt;',
              symbol,
              '&lt;title&gt;', esc(title_txt), '&lt;/title&gt;',
              svg_text(
                px + dx,
                py - 9,
                sub_d$label[i],
                size = 11,
                colour = "#666666",
                anchor = anchor,
                weight = 500,
                class = "hover-label"
              ),
              '&lt;/g&gt;',
              persistent
            )
          },
          character(1)
        ),
        collapse = ""
      )
    }

    # --------------------------------------------------------
    # Active variable
    # --------------------------------------------------------

    variable_html &lt;- ""

    if ("variables" %in% layers && nrow(active_d) &gt; 0) {

      variable_html &lt;- paste(
        vapply(
          seq_len(nrow(active_d)),
          function(i) {

            px &lt;- sx(active_d$dim1[i])
            py &lt;- sy(active_d$dim2[i])

            dx &lt;- if (active_d$dim1[i] &gt; mean(xr)) -10 else 10
            anchor &lt;- if (active_d$dim1[i] &gt; mean(xr)) "end" else "start"

            title_txt &lt;- paste0(
              active_d$label[i],
              " | Dim 1: ", sprintf("%.3f", active_d$dim1[i]),
              " | Dim 2: ", sprintf("%.3f", active_d$dim2[i])
            )

            label_html &lt;- ""
            if (isTRUE(input$labels)) {
              label_html &lt;- svg_text(
                px + dx,
                py - 9,
                active_d$label[i],
                size = 12,
                colour = "#333333",
                anchor = anchor,
                weight = 500
              )
            }

            paste0(
              '&lt;circle cx="', px, '" cy="', py, '" r="7"',
              ' fill="#4E79A7" stroke="white" stroke-width="1.5"&gt;',
              '&lt;title&gt;', esc(title_txt), '&lt;/title&gt;',
              '&lt;/circle&gt;',
              label_html
            )
          },
          character(1)
        ),
        collapse = ""
      )
    }

    # --------------------------------------------------------
    # SVG
    # --------------------------------------------------------

    html &lt;- paste0(
      '&lt;svg viewBox="0 0 ', W, ' ', H, '"',
      ' preserveAspectRatio="xMidYMid meet"',
      ' style="width:100%;height:auto;display:block;"&gt;',

      '&lt;rect x="', left, '" y="', top, '"',
      ' width="', right - left, '" height="', bottom - top, '"',
      ' fill="#ffffff" stroke="#eeeeee"/&gt;',

      axis_html,
      cluster_html,
      subfield_html,
      variable_html,

      '&lt;text x="', left, '" y="525" text-anchor="start"',
      ' font-size="11" fill="#777777"&gt;← Academic / linear&lt;/text&gt;',

      '&lt;text x="', right, '" y="525" text-anchor="end"',
      ' font-size="11" fill="#777777"&gt;Vocational / delayed →&lt;/text&gt;',

      '&lt;text x="530" y="552" text-anchor="middle"',
      ' font-size="12" font-weight="600" fill="#555555"&gt;',
      'Axis 1 — Life-course position and institutionalised access pathway',
      '&lt;/text&gt;',

      '&lt;text x="25" y="270" transform="rotate(-90 25 270)"',
      ' text-anchor="middle" font-size="12" font-weight="600" fill="#555555"&gt;',
      'Axis 2 — Academic and institutional constraint gradient',
      '&lt;/text&gt;',

      '&lt;/svg&gt;'
    )

    HTML(html)
  })

  output$selection_note &lt;- renderUI({

    selected &lt;- input$subfields

    if (is.null(selected) || length(selected) == 0) {
      return(NULL)
    }

    d &lt;- coords[
      coords$type == "subfield" &
        coords$label %in% selected,
      ,
      drop = FALSE
    ]

    if (nrow(d) == 0) {
      return(NULL)
    }

    lines &lt;- vapply(
      seq_len(nrow(d)),
      function(i) {
        paste0(
          "&lt;strong&gt;", esc(d$label[i]), "&lt;/strong&gt;",
          " · ", d$stem[i],
          " · Dim 1 = ", sprintf("%.3f", d$dim1[i]),
          " · Dim 2 = ", sprintf("%.3f", d$dim2[i])
        )
      },
      character(1)
    )

    div(
      class = "selection-note",
      HTML(paste(lines, collapse = "&lt;br&gt;"))
    )
  })
}

shinyApp(
  ui = ui,
  server = server
)
